function extractMedicationLines(dischargeText) {
  const lines = logicalLines(dischargeText);
  const medicationCue = /(?:mg|mcg|puffs?|tablet|capsule|by mouth|daily|twice daily|inhaler|medication)/i;
  const sectionStop = /^(?:home instructions|follow-?up|return precautions|allergies)\s*:/i;
  let inMedicationSection = false;
  const medicationLines = [];

  for (const line of lines) {
    if (/^discharge medications?\s*:?$/i.test(line)) {
      inMedicationSection = true;
