    }

    if (sectionStop.test(line)) {
      inMedicationSection = false;
    }

    if ((inMedicationSection || medicationCue.test(line)) && !/^discharge medications?\s*:?$/i.test(line)) {
      medicationLines.push(line.replace(/^discharge medications?\s*:\s*/i, ""));
    }
  }

  return medicationLines;
}

function parseMedication(line) {
  const cleaned = cleanLine(line);
  const name = cleaned.match(/^([A-Za-z][A-Za-z0-9/-]*)/)?.[1] || "Medication";
  const dose = cleaned.match(/\b\d+(?:\.\d+)?\s*(?:mg|mcg|g|ml|mL|units?|puffs?|tablets?|capsules?)\b/i)?.[0] || "Not clearly listed";
